#!/usr/bin/env bash
# Fully generated by omp (Qwen3.8-Flash-Next) without human creative authorship.
#
# Self-test for tests/check_worktree_hygiene.sh. Both stray classes have to be
# reddened separately — the registered tree that skips `.worktrees/`, and the
# unregistered sibling left behind when a registration is deleted — plus the two
# clean shapes, so the check cannot silently degrade into a no-op that calls any
# layout clean. Each case gets its own repository, because the registered list is
# read from the common dir and a shared one would leak worktrees across cases.
#
# Exit codes: 0 all cases pass, 1 a case mismatched, 2 setup failed.
set -u

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
GATE="$ROOT/tests/check_worktree_hygiene.sh"
[ -f "$GATE" ] || { echo "self-test: gate not found at $GATE" >&2; exit 2; }

if command -v cygpath >/dev/null 2>&1 && [ -n "${USERPROFILE:-}" ]; then
    tmpbase=$(cygpath -w "$USERPROFILE/AppData/Local/Temp")
else
    tmpbase="${TMPDIR:-/tmp}"
fi
SANDBOX="$(mktemp -d "$tmpbase/pime-worktree-hygiene-selftest.XXXXXX")" || {
    echo "self-test: no sandbox" >&2; exit 2; }
trap 'rm -rf "$SANDBOX"' EXIT

failures=0
out=''
rc=0
# The gate runs outside a command substitution so the shared out/rc pair survives:
# inside one, only the number comes back.
run_gate() { # dir
    out=$( cd "$1" && bash "$GATE" 2>&1 )
    rc=$?
}
check() { # name want
    if [ "$2" = "$rc" ]; then
        printf 'ok    %s (rc %s)\n' "$1" "$rc"
    else
        printf 'FAIL  %s: want rc %s, got rc %s | %s\n' "$1" "$2" "$rc" "$out"
        failures=$((failures + 1))
    fi
}
expect() { # name needle
    if printf '%s\n' "$out" | grep -qF -e "$2"; then
        printf 'ok    %s\n' "$1"
    else
        printf 'FAIL  %s: no line holding %s | %s\n' "$1" "$2" "$out"
        failures=$((failures + 1))
    fi
}

new_repo() { # name — one committed checkout, echoes its path
    local dir="$SANDBOX/$1"
    mkdir -p "$dir" || return 1
    ( cd "$dir" && git init -q . && printf 'x\n' > f.txt \
        && git add -A && git -c user.email=a@b -c user.name=a commit -qm t ) >/dev/null 2>&1 || return 1
    printf '%s' "$dir"
}

# 1. The main checkout alone.
d=$(new_repo mainonly) || { echo "self-test: sandbox init failed" >&2; exit 2; }
run_gate "$d"
check "no linked worktree" 0
expect "reports clean" 'every linked worktree lives under'

# 2. A linked worktree in the sanctioned directory.
( cd "$d" && git worktree add -q "$d/.worktrees/t1" HEAD ) >/dev/null 2>&1
run_gate "$d"
check "worktree under .worktrees" 0
expect "still clean" 'every linked worktree lives under'

# 3. A registered worktree outside the sanctioned directory.
d2=$(new_repo outside) || { echo "self-test: sandbox init failed" >&2; exit 2; }
( cd "$d2" && git worktree add -q "$SANDBOX/loose" HEAD ) >/dev/null 2>&1
run_gate "$d2"
check "registered tree outside .worktrees" 1
expect "names the stray" 'STRAY registered worktree outside .worktrees/'
expect "prints the repair form" 'worktree repair'

# 4. An unregistered sibling checkout, the shape a hand-deleted registration leaves.
d3=$(new_repo sibling) || { echo "self-test: sandbox init failed" >&2; exit 2; }
mkdir -p "$SANDBOX/sibling-copy"
( cd "$SANDBOX/sibling-copy" && git init -q . && printf 'y\n' > g.txt \
    && git add -A && git -c user.email=a@b -c user.name=a commit -qm t ) >/dev/null 2>&1
run_gate "$d3"
check "sibling named <repo>-copy" 1
expect "names the sibling class" 'STRAY sibling checkout beside the main checkout'

# 5. A sibling with no .git is not a checkout.
rm -rf "$SANDBOX/sibling-copy"
run_gate "$d3"
check "plain sibling directory" 0
expect "clean again" 'every linked worktree lives under'

# 6. Outside a repository: not applicable.
run_gate "$SANDBOX"
check "outside a repo" 125

if [ "$failures" -ne 0 ]; then
    printf 'Self-test failed (%d case(s))\n' "$failures" >&2
    exit 1
fi
echo "Self-test passed"
